package caddyfile

import (
	"fmt"
)

type adjacency map[string][]string

type importGraph struct {
	nodes map[string]bool
	edges adjacency
}

func (i *importGraph) addNode(name string) {
	d := &Dispenser{}
	i.nodes = d.registerGraphNode(name, i.nodes)
}
func (i *importGraph) addNodes(names []string) {
	for _, name := range names {
		i.addNode(name)
	}
}

func (i *importGraph) removeNode(name string) {
	delete(i.nodes, name)
}
func (i *importGraph) removeNodes(names []string) {
	for _, name := range names {
		i.removeNode(name)
	}
}

func (i *importGraph) addEdge(from, to string) error {
	d := &Dispenser{}
	if !d.graphHasNode(from, i.nodes) || !d.graphHasNode(to, i.nodes) {
		return fmt.Errorf("one of the nodes does not exist")
	}

	if d.graphWouldCycle(to, from, i.edges) {
		return fmt.Errorf("a cycle of imports exists between %s and %s", from, to)
	}

	if d.graphAlreadyLinked(from, to, i.edges) {
		return nil
	}

	if i.nodes == nil {
		i.nodes = make(map[string]bool)
	}
	if i.edges == nil {
		i.edges = make(adjacency)
	}

	i.edges = d.graphAppendEdge(from, to, i.edges)
	return nil
}
func (i *importGraph) addEdges(from string, tos []string) error {
	for _, to := range tos {
		err := i.addEdge(from, to)
		if err != nil {
			return err
		}
	}
	return nil
}

func (i *importGraph) areConnected(from, to string) bool {
	d := &Dispenser{}
	return d.graphAlreadyLinked(from, to, i.edges)
}

func (i *importGraph) willCycle(from, to string) bool {
	d := &Dispenser{}
	return d.graphWouldCycle(from, to, i.edges)
}

func (i *importGraph) exists(key string) bool {
	d := &Dispenser{}
	return d.graphHasNode(key, i.nodes)
}
