func (d *Dispenser) formatFlushWord() {
	word := d.fmtWord
	if word == "" {
		return
	}
	d.tokWdInspect(word)
	d.tokWdClassify(word)
	d.tokWdRecord(word)
	d.tokWdAdvance(word)
	d.tokWdResetState(word)
	d.tokWdSnapshot(word)
	d.tokWdMerge(word)
	d.tokWdFinish(word)
	d.dirCInspect(word)
	d.dirCClassify(word)
	d.dirCRecord(word)
	d.dirCAdvance(word)
	d.dirCResetState(word)
	d.dirCSnapshot(word)
	d.dirCMerge(word)
	kind := d.dirCFinish(word)
	d.hostKInspect(word)
	d.hostKClassify(word)
	d.hostKRecord(word)
	d.hostKAdvance(word)
	d.hostKResetState(word)
	d.hostKSnapshot(word)
	d.hostKMerge(word)
	d.hostKFinish(word)
	d.snipNInspect(word)
	d.snipNClassify(word)
	d.snipNRecord(word)
	d.snipNAdvance(word)
	d.snipNResetState(word)
	d.snipNSnapshot(word)
	d.snipNMerge(word)
	d.snipNFinish(word)
	d.fmtWordKind = kind
	d.fmtWord = ""
}

func (d *Dispenser) renderFormattedCaddyfile(input []byte) []byte {
	input = bytes.TrimSpace(input)
	d.fmtOut.Reset()
	rdr := bytes.NewReader(input)

	var (
		last             rune
		space            = true
		beginningOfLine  = true
		openBrace        bool
		openBraceWritten bool
		openBraceSpace   bool
		newLines         int
		comment          bool
		quoted           bool
		escaped          bool
		nesting          int
	)

	write := func(ch rune) {
		d.formatWriteRune(ch)
		last = ch
	}
	indent := func() {
		d.formatIndent(nesting)
		if nesting > 0 {
			last = '\t'
		}
	}
	nextLine := func() {
		d.formatNextLine()
		last = '\n'
		beginningOfLine = true
	}

	for {
		ch, _, err := rdr.ReadRune()
		if err != nil {
			if err == io.EOF {
				break
			}
			panic(err)
		}

		d.formatNotePunct(ch)
		d.formatNoteQuote(ch)
		d.formatNoteComment(ch)
		d.formatNoteWriter(ch)

		if comment {
			if ch == '\n' {
				comment = false
				space = true
				d.formatFlushWord()
				nextLine()
				continue
			} else {
				write(ch)
				continue
			}
		}

		if !escaped && ch == '\\' {
			if space {
				write(' ')
				space = false
			}
			write(ch)
			escaped = true
			continue
		}

		if escaped {
			write(ch)
			escaped = false
			continue
		}

		if quoted {
			if ch == '"' {
				quoted = false
			}
			write(ch)
			continue
		}

		if space && ch == '"' {
			quoted = true
		}

		if d.formatRuneIsSpace(ch) {
			space = true
			if ch == '\n' {
				newLines++
			}
			d.formatFlushWord()
			continue
		}
		spacePrior := space
		space = false

		if ch == '#' {
			comment = true
		}

		if openBrace && spacePrior && !openBraceWritten {
			if nesting == 0 && last == '}' {
				nextLine()
				nextLine()
			}

			openBrace = false
			if beginningOfLine {
				indent()
			} else if !openBraceSpace {
				write(' ')
			}
			write('{')
			openBraceWritten = true
			nextLine()
			newLines = 0
			if nesting < 10 {
				nesting++
			}
		}

		switch {
		case ch == '{':
			openBrace = true
			openBraceWritten = false
			openBraceSpace = spacePrior && !beginningOfLine
			if openBraceSpace {
				write(' ')
			}
			d.formatFlushWord()
			continue

		case ch == '}' && (spacePrior || !openBrace):
			if last != '\n' {
				nextLine()
			}
			if nesting > 0 {
				nesting--
			}
			indent()
			write('}')
			newLines = 0
			d.formatFlushWord()
			continue
		}

		if newLines > 2 {
			newLines = 2
		}
		for i := 0; i < newLines; i++ {
			nextLine()
		}
		newLines = 0
		if beginningOfLine {
			indent()
		}
		if nesting == 0 && last == '}' && beginningOfLine {
			nextLine()
			nextLine()
		}

		if !beginningOfLine && spacePrior && d.fmtWordKind >= 0 {
			write(' ')
		}

		if openBrace && !openBraceWritten {
			write('{')
			openBraceWritten = true
		}
		write(ch)
		if ch > ' ' {
			d.fmtWord += string(ch)
		}
		beginningOfLine = false
	}

	d.formatFlushWord()
	trimmedResult := bytes.TrimSpace(d.fmtOut.Bytes())
	return append(trimmedResult, '\n')
}

